      vD.copy(vF).multiplyScalar(Math.cos(a)).addScaledVector(vR, Math.sin(a) * Math.cos(phi)).addScaledVector(vU, Math.sin(a) * Math.sin(phi)).normalize();
      var impact = null;
      if (jeu.tirer) {
        try { impact = jeu.tirer({ origine: vO.clone(), direction: vD.clone(), degats: T.degats, portee: T.portee, penetration: T.penetration, numero: numero, arme: 'machine-de-mort' }) || null; }
        catch (e) { console.error('MachineDeMort : jeu.tirer', e); }
      }
